def decode(value):
    return (value.replace('@LT@', chr(60)).replace('@GT@', chr(62))
            .replace('@AMP@', chr(38)).replace('@MDASH@', chr(8212)))


def require(ok, message):
    if not ok:
        raise RuntimeError(message)


def node_checks(html):
    node = shutil.which('node')
    require(node is not None, 'Node.js is required for node --check and offline tests; nothing was written')
    lt, gt = chr(60), chr(62)
    pattern = lt + r'script\b([^' + gt + r']*)' + gt + r'(.*?)' + lt + r'/script\s*' + gt
    blocks = re.findall(pattern, html, re.S | re.I)
    checked = 0
    with tempfile.TemporaryDirectory(prefix='k2-tests-') as directory:
        root = Path(directory)
        for index, (attrs, source) in enumerate(blocks):
            if re.search(r'\bsrc\s*=', attrs, re.I):
                continue
            kind = re.search(r'''\btype\s*=\s*["']([^"']+)["']''', attrs, re.I)
            if kind and kind.group(1).lower() not in ('text/javascript', 'application/javascript', 'module'):
                continue
            path = root / ('inline-' + str(index) + '.js')
            path.write_text(source, encoding='utf-8')
            result = subprocess.run([node, '--check', str(path)], capture_output=True, text=True, timeout=60)
            require(result.returncode == 0, 'node --check failed: ' + result.stderr[-1800:])
            checked += 1
        require(checked != 0, 'no inline JavaScript found')
        print('  node --check: PASS (%d full inline scripts)' % checked)
        candidate = root / 'candidate.html'
        candidate.write_text(html, encoding='utf-8')
        suite = root / 'offline.js'
        suite.write_text(decode(OFFLINE_ENCODED), encoding='utf-8')
        result = subprocess.run([node, str(suite), str(candidate)], capture_output=True, text=True, timeout=120)
        require(result.returncode == 0, 'K.2 offline tests failed:\n' + result.stdout[-1800:] + result.stderr[-2500:])
        print(result.stdout.rstrip())


def atomic_replace(path, payload, mode):
    fd, temp = tempfile.mkstemp(prefix='.brickK2-', dir=str(path.parent))
    try:
        with os.fdopen(fd, 'wb') as f:
            f.write(payload)
            os.fchmod(f.fileno(), mode)
            f.flush()
            os.fsync(f.fileno())
        os.replace(temp, path)
    finally:
        if os.path.exists(temp):
            os.unlink(temp)


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--dir', default='.', help='directory containing chat_test.html and main.py')
    parser.add_argument('--dry-run', action='store_true')
    args = parser.parse_args()
    root = Path(args.dir).resolve()
    path, backend = root / 'chat_test.html', root / 'main.py'
    backup = path.with_name(path.name + '.bak-brickK2')
    raw, backend_raw = path.read_bytes(), backend.read_bytes()
    text = raw.decode('utf-8')
    require('BRICK F.3d' in text, 'BRICK F.3d is required in chat_test.html')
    require('BRICK K.1.5' in backend_raw.decode('utf-8'), 'BRICK K.1.5 is required in main.py (read-only)')
    require(MARKER not in text, 'BRICK K.2 already present; refusing second run')
    require(not backup.exists(), 'chat_test.html.bak-brickK2 exists; it will never be overwritten')
    normalized = text.replace('\r\n', '\n')
    require('\r' not in normalized, 'bare-CR line endings are unsupported')
    crlf = '\r\n' in text
    require(not crlf or '\n' not in text.replace('\r\n', ''), 'mixed LF/CRLF line endings')
    anchors = [(name, decode(old), decode(new), expected) for name, old, new, expected in ANCHORS_ENCODED]
    print('Target: ' + str(path))
    print('Backend prerequisite: ' + str(backend) + ' (read-only)')
    for name, old, new, expected in anchors:
        count = normalized.count(old)
        print('  %s: found %d, expected %d' % (name, count, expected))
        require(count == expected, name + ' exact anchor count mismatch')
    output = normalized
    for name, old, new, expected in anchors:
        output = output.replace(old, new, expected)
    restored = output
    for name, old, new, expected in reversed(anchors):
        restored = restored.replace(new, old, expected)
    require(restored == normalized, 'edit footprint differs from the eight approved anchors')
    require(output.count("const SYNC_KEYS=['funnel','launch','reality','content','community','leads','actions','library','dna'];") == normalized.count("const SYNC_KEYS=['funnel','launch','reality','content','community','leads','actions','library','dna'];"), 'SYNC_KEYS changed unexpectedly')
    node_checks(output)
    payload = (output.replace('\n', '\r\n') if crlf else output).encode('utf-8')
    if args.dry_run:
        print('DRY RUN PASS: no target or backup written')
        return
    require(path.read_bytes() == raw, 'chat_test.html changed during checks; refusing write')
    require(backend.read_bytes() == backend_raw, 'backend prerequisite changed during checks; refusing write')
    mode = stat.S_IMODE(path.stat().st_mode)
    with open(backup, 'xb') as f:
        f.write(raw)
        os.fchmod(f.fileno(), mode)
        f.flush()
        os.fsync(f.fileno())
    atomic_replace(path, payload, mode)
    print('APPLIED: ' + str(path))
    print('BACKUP: ' + str(backup))
    print('Hard-refresh the browser after deployment.')


if __name__ == '__main__':
    try:
        main()
    except (OSError, UnicodeError, RuntimeError, subprocess.TimeoutExpired) as exc:
        print('ABORT: ' + str(exc), file=sys.stderr)
        print('No successful apply was confirmed. Any created backup remains available.', file=sys.stderr)
        sys.exit(1)
